import{_ as e,o,c as n,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Acerca de","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/about.md","filePath":"es-ES/user-guide/settings/about.md","lastUpdated":1785993908000}'),r={name:"es-ES/user-guide/settings/about.md"};function s(t,a,c,l,u,d){return o(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="acerca-de" tabindex="-1">Acerca de <a class="header-anchor" href="#acerca-de" aria-label="Permalink to &quot;Acerca de&quot;">​</a></h1><p>Muestra los números de versión de los componentes App, Core, Service y CLI (con color según si el servicio está sano en ese momento), una breve descripción de Lertaro, y enlaces a la página de inicio del proyecto y a la guía de usuario en línea.</p><h2 id="carpetas-de-configuracion" tabindex="-1">Carpetas de configuración <a class="header-anchor" href="#carpetas-de-configuracion" aria-label="Permalink to &quot;Carpetas de configuración&quot;">​</a></h2><p>Dos enlaces más, justo debajo de esos, abren las carpetas desde las que Lertaro lee y en las que escribe su propia configuración — cada uno muestra la ruta real como texto del enlace pulsable, creando primero la carpeta si aún no existe:</p><ul><li><strong>Carpeta de configuración de usuario</strong> — la carpeta por usuario que contiene <code>user-settings.json</code>. Cada vez que se guarda la configuración, el archivo anterior se rota a <code>user-settings.json.bak.1</code> (desplazando hacia abajo cualquier copia de seguridad más antigua, hasta <code>.bak.5</code>) antes de escribir el nuevo, de modo que una edición defectuosa o un fallo a mitad de guardado siempre deja una copia reciente desde la que restaurar.</li><li><strong>Carpeta de configuración del sistema</strong> — la carpeta compartida, de ámbito de todo el equipo, usada por el servicio en segundo plano (<code>machine-settings.json</code>, cachés del índice y registros del lado del servicio).</li></ul><h2 id="buscar-actualizaciones" tabindex="-1">Buscar actualizaciones <a class="header-anchor" href="#buscar-actualizaciones" aria-label="Permalink to &quot;Buscar actualizaciones&quot;">​</a></h2><ul><li>Botón <strong>Buscar actualización</strong> — consulta si hay una versión más reciente; la propia etiqueta del botón refleja el progreso (&quot;Comprobando...&quot;, y luego &quot;actualizado&quot; o el número de la nueva versión encontrada).</li><li>Si una cuenta sin privilegios de administrador no puede detener el servicio en segundo plano para instalar una actualización en el sitio, un banner de aviso lo explica y te remite en su lugar a la página de descarga manual.</li><li>Una vez encontrada una nueva versión: <ul><li><strong>Actualización automática silenciosa</strong> — descarga e instala en segundo plano, mostrando una barra de progreso, y luego reinicia Lertaro automáticamente.</li><li><strong>Ir a la página de descarga</strong> — abre la página de la versión en GitHub en tu navegador para una instalación manual.</li></ul></li></ul><p>Esto es un reflejo de las casillas <strong>Buscar actualizaciones automáticamente</strong> / <strong>Actualización silenciosa automática</strong> en <a href="./general.html#sistema">General → Sistema</a> — esas controlan si esta comprobación ocurre automáticamente al iniciar; esta página te permite dispararla manualmente en cualquier momento.</p>',8)])])}const m=e(r,[["render",s]]);export{g as __pageData,m as default};
